Use a min-heap to always extract the smallest element across all lists:

```cpp
vector<int> mergeKSorted(vector<vector<int>>& lists) {
    // {value, list_index, element_index}
    priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<>> pq;

    for (int i = 0; i < (int)lists.size(); i++)
        if (!lists[i].empty())
            pq.push({lists[i][0], i, 0});

    vector<int> result;
    while (!pq.empty()) {
        auto [val, i, j] = pq.top(); pq.pop();
        result.push_back(val);
        if (j + 1 < (int)lists[i].size())
            pq.push({lists[i][j+1], i, j+1});
    }
    return result;
}
```

O(N log k) where N is total elements and k is number of lists.
